import{_ as p,c as e,o as t,ah as r}from"./chunks/framework.Dnh4IO1K.js";const d=JSON.parse('{"title":"26、【大畜】 乾下艮上","description":"周易阐真 - 26、【大畜】 乾下艮上","frontmatter":{"title":"26、【大畜】 乾下艮上","description":"周易阐真 - 26、【大畜】 乾下艮上"},"headers":[],"relativePath":"zh/classics/chanzhen/027.md","filePath":"zh/classics/chanzhen/027.md"}'),s={name:"zh/classics/chanzhen/027.md"};function n(c,a,i,o,h,l){return t(),e("div",null,[...a[0]||(a[0]=[r('<blockquote><p>彖曰：大畜，刚健笃实，辉光日新。其德刚上而尚贤，能止健，大正也。不家食吉，养贤也。利涉大川，应乎天也。</p></blockquote><h1 id="_26、【大畜】-乾下艮上" tabindex="-1">26、【大畜】 乾下艮上 <a class="header-anchor" href="#_26、【大畜】-乾下艮上" aria-label="Permalink to “26、【大畜】 乾下艮上”">​</a></h1><p>初九：有厉，利已。</p><p>九二：舆说复副本。</p><p>九三：良马逐，利艰贞。日闲舆卫，利有攸往。</p><p>六四：童牛之牿，元吉。</p><p>六五：豮豕之牙，吉。</p><p>上九：何天之衢，亨。</p><h2 id="孔易阐真-​" tabindex="-1">孔易阐真 ​ <a class="header-anchor" href="#孔易阐真-​" aria-label="Permalink to “孔易阐真 ​”">​</a></h2><p>大象：天在山中，大畜。君子以多识前言往行，以畜其德。</p><p>大畜者，积聚大也。上艮山，下乾天，是天在山中也。天大山小，外小而内大，此大畜之象也。</p><p>君子有见于此，知人之不能增益其德者，皆由自恃才智，自高自大，不知法古圣先贤之故。以是多识前人之言、往古之行，扩充识见，以畜其德焉。圣贤心法命脉，皆藏于经书之中。前人之言，言其德也；往古之行，行其德也。若能博学而笃志，切问而近思，则晤对圣贤，所言者皆前人之言，所行者皆往古之行。言行无亏，其德日畜日大，方且尽性至命，性命俱了，与天同长久，与山同坚固，其畜之大何如乎!</p><h2 id="悟元子注解-​" tabindex="-1">悟元子注解 ​ <a class="header-anchor" href="#悟元子注解-​" aria-label="Permalink to “悟元子注解 ​”">​</a></h2><p>畜，敕六反。说，音脱。复副本，音福。豮，音焚。衢，音渠。</p><p>大畜者，大养之义。卦德上艮止，下乾健，有健而能止，故谓大畜。此温养圣胎之卦，承上复卦而来。复者，复其先天之气也。当先天之气来复，于内自微而著，还其乾元面目，命基已固，圣胎已结，自有为而入无为，可以谨封牢藏，防危虑险，温养沐浴，期于大化神妙不测之地，为金刚不坏之物。</p><p>是道也，利于止健，不利于用健，故曰利贞。贞者，静也。止健者，养健也。养健之功，即守中抱一之功。守中抱一，宜静而不宜动，静则保健，动则伤健。止非绝世离尘，静非空寂无为，其中有抽添加减，内外兼修之道，故必不家食，方能大畜而致吉。不家食者，是外炉加减，内运真火，止于内而又止于外，绵绵若存，勿忘勿助，即遇大险大难之境，不动不摇，方是真畜，方是畜之大，是以又利于涉大川也。大川之涉，所以养于内而验于外，即九年面壁之功。面壁者，如壁列万仞，离种种边，止于不识不知，打破虚空地位也。打破虚空，圣胎脱化，形神俱妙，与道合真，畜之大而成之大，与天为徒矣。</p><p>初九，在大畜之始，进健则凶，止健则吉，有厉利己，正当弃有为而入无为之时。此养健于初也。</p><p>九二，刚以柔用，保惜圣胎，待时脱化，如舆说复副本，则车不行矣。修道者，刚健归中，圣胎已结，急须住火停轮，不可更进其健，有伤元气者。此养健得中也。</p><p>九三，养健已到，气足神全，诚于中而将达于外，如良马逐而欲行矣。虽然圣胎完成，犹有一身阴气未尝化尽，全在艰辛守贞，一意不散，如日闲舆卫，时时防跌，十月功完，自然脱化，则利有攸往矣。此养健防危也。</p><p>六四，应于初阳，健德方生，而即养之，如童牛之牿也。牛性驯顺，其健在角，牛在于童，其角方生，方生能养，元气不散，渐长渐养，终必养至于纯全之处，其吉已在于方健之养。此养健而坚固元气也。</p><p>六五，正当大畜之时，以阴养阳，如豮贲豕也。豕之去势曰豮。豕去其势，则气质俱化，虚心而全实腹，如豮豕之牙也。豕柔牙刚，以柔养刚，刚得柔养而无伤。此养健而混合阴阳也。</p><p>上九，在大畜之终，功完行满，霹雳一声，真人出现，惊愚骇俗，始于有作无人见，及至无为众始知，何天之衢，谁不称哉！</p><p>修道者，而至于脱胎成真，身外有身，超出乎天地之外，不但成己，而且成物，畜之大而显之大，其亨为何如乎！此养健而归于神化也。</p><p>然则温养圣胎之道，总要知的大畜健而止。既健又止，始则有为，终则无为，健而止于至善无恶，浑然太极，一气流行，有无俱不立，物我悉归空，性命双修之道尽矣。</p>',24)])])}const m=p(s,[["render",n]]);export{d as __pageData,m as default};
